func runOne(o options, abDir string, a arm, taskName string, rep int) (res result) { res = result{Arm: a.Name, Task: taskName, Rep: rep} work, err := os.MkdirTemp("", "abrun-work-") if err != nil { res.Err = err.Error() return res } // Successful implementations also need source evidence for structural review. defer func() { if o.keep { res.WorkDir = work return } _ = os.RemoveAll(work) //nolint:errcheck // best-effort cleanup after the result is recorded }() pkgDir := filepath.Join(work, taskName) if err := os.CopyFS(pkgDir, os.DirFS(filepath.Join(abDir, taskName))); err != nil { res.Err = fmt.Sprintf("copy fixture: %v", err) return res } if err := os.WriteFile(filepath.Join(work, "go.mod"), []byte("module abeval

go 1.27
"), 0o644); err != nil { res.Err = err.Error() return res } before, err := analyze(pkgDir) if err != nil { res.Err = fmt.Sprintf("analyze fixture: %v", err) return res } res.Before = before beforeDigest, err := fixtureDigest(pkgDir) if err != nil { res.Err = fmt.Sprintf("digest fixture: %v", err) return res } // measure re-reads everything a turn can change. It runs after the first // session and again after a repair turn, so the recorded numbers always // describe the tree as the run left it. It reports false when the run // cannot continue. measure := func(final string) bool { if afterDigest, err := fixtureDigest(pkgDir); err == nil { res.Edited = afterDigest != beforeDigest } else if res.Err == "" { res.Err = fmt.Sprintf("digest result: %v", err) return false } after, err := analyze(pkgDir) if err != nil { if res.Err == "" { res.Err = fmt.Sprintf("analyze result: %v", err) } return false } res.After = after res.Delta = after.sub(before) res.LineGatePass = res.Delta.Lines <= 0 res.EmptyDiff = !res.Edited && res.Err == "" && final != "" res.GoFail, res.Build = "", false if err := goCmd(o.timeout, work, "build", "./..."); err != nil { res.GoFail = err.Error() } else { res.Build = true } res.ModelTests, res.ModelTestFail = "skipped", "" if after.TestFiles > 0 { res.ModelTests = "pass" if err := goCmd(o.timeout, work, "test", "-count=1", "./..."); err != nil { res.ModelTests = "fail" res.ModelTestFail = err.Error() } } return true } turn := runSession(o, a, work, fmt.Sprintf(o.prompt, taskName)) res.merge(turn) // The transcript is written before anything is measured, so it survives even // a run that fails from here on. A final message that claims a measurement // is only checkable against the commands the session actually ran. if err := appendTrace(work, turn.out); err == nil && o.keep { res.Trace = filepath.Join(work, traceFile) } res.Leaked = bytes.Contains(turn.out, []byte(abDir)) if !measure(turn.final) { return res } golden := filepath.Join(abDir, "_golden", taskName) // The repair loop closes the gap stage 2 measured: a session that is handed // its own numbers back, in the harness's own counting convention, together // with the independent failure, repairs what a generic re-review does not. // The probe runs on a throwaway copy of the whole module, so the golden // never enters the tree the model can see. if o.repair && res.Err == "" { probePass, probeFail, probeErr := probeGolden(o.timeout, work, taskName, golden) switch { case probeErr != nil: res.Err = fmt.Sprintf("probe golden: %v", probeErr) return res case res.LineGatePass && probePass: // Nothing to repair; the loop costs no extra turn. default: pre := res.After res.RepairFired, res.PreRepair, res.PreRepairGolden = true, &pre, probePass res.RepairFeedback = repairFeedback(taskName, before.Lines, pre.Lines, probeFail) repair := runSession(o, a, work, res.RepairFeedback) res.merge(repair) if err := appendTrace(work, repair.out); err == nil && o.keep { res.Trace = filepath.Join(work, traceFile) } if bytes.Contains(repair.out, []byte(abDir)) { res.Leaked = true } if !measure(repair.final) { return res } } } // Run the model's tests first, then isolate them to avoid name collisions // or a model test being the reason the independent golden check passes. if err := hideTestFiles(pkgDir); err != nil { res.Err = fmt.Sprintf("hide model tests: %v", err) return res } if err := os.CopyFS(pkgDir, os.DirFS(golden)); err != nil { res.Err = fmt.Sprintf("copy golden: %v", err) return res } if err := goCmd(o.timeout, work, "test", "./"+taskName+"/..."); err != nil { res.GoFail = err.Error() res.BehaviorFailure, res.HarnessFailure = classifyGolden(res.Build, err.Error()) } else { res.Golden = true } return res }

func TestAnalyzeIncludesNestedGoFiles(t *testing.T) { root := t.TempDir() writeTestFile(t, filepath.Join(root, "fixture.go"), "package fixture

type Local struct{}
func Top() {}
") writeTestFile(t, filepath.Join(root, "nested", "nested.go"), "package nested
type Service interface{ Run() }
func Use() {}") writeTestFile(t, filepath.Join(root, "nested", "nested_test.go"), "package nested
") got, err := analyze(root) if err != nil { t.Fatalf("analyze(%q) error = %v, want nil", root, err) } want := metrics{Lines: 7, Files: 2, TestFiles: 1, Types: 2, Interfaces: 1, Funcs: 2, Exported: 4} if got != want { t.Errorf("analyze(%q) = %+v, want %+v", root, got, want) } }

func TestProbeGoldenLeavesTreeUntouched(t *testing.T) { work, golden := t.TempDir(), t.TempDir() writeTestFile(t, filepath.Join(work, "go.mod"), "module abeval

go 1.27
") writeTestFile(t, filepath.Join(work, "task/task.go"), "package task

func Value() int { return 2 }
") writeTestFile(t, filepath.Join(work, "task/task_test.go"), "package task

import "testing"

func TestModel(t *testing.T) {}
") writeTestFile(t, filepath.Join(golden, "golden_test.go"), "package task

import "testing"

func TestGolden(t *testing.T) {
	if Value() != 1 {
		t.Fatalf("Value() = %d, want 1", Value())
	}
}
") pass, failure, err := probeGolden(time.Minute, work, "task", golden) if err != nil { t.Fatalf("probeGolden error = %v, want nil", err) } if pass { t.Error("probeGolden = true, want the golden assertion to fail") } if !strings.Contains(failure, "Value() = 2, want 1") { t.Errorf("probeGolden failure = %q, want the assertion", failure) } entries, err := os.ReadDir(filepath.Join(work, "task")) if err != nil { t.Fatal(err) } var names []string for _, e := range entries { names = append(names, e.Name()) } if len(names) != 2 || names[0] != "task.go" || names[1] != "task_test.go" { t.Errorf("probe left %v in the model's tree, want only task.go and task_test.go", names) } // And it answers true when the package satisfies the golden. writeTestFile(t, filepath.Join(work, "task/task.go"), "package task

func Value() int { return 1 }
") if pass, _, err := probeGolden(time.Minute, work, "task", golden); err != nil || !pass { t.Errorf("probeGolden(passing) = %v, err = %v, want true and nil", pass, err) } }

func TestRunOneRepairLoop(t *testing.T) { const fixture = "package task

func Value() int { return 1 }
" const grown = "package task

// grown past the gate
func helper() int { return 1 }

func Value() int { return helper() }
" const repaired = "package task

func Value() int { return 1 } // repaired
" for _, tt := range []struct { name string repair bool wantFired bool wantGate bool wantLines int wantPreGold bool }{ {name: "loop off leaves the growth", wantLines: 3}, {name: "loop on repairs it", repair: true, wantFired: true, wantGate: true, wantLines: 0, wantPreGold: true}, } { t.Run(tt.name, func(t *testing.T) { bin, corpus, model := t.TempDir(), t.TempDir(), t.TempDir() cli := filepath.Join(bin, "claude") // The turn counter lives in the model directory: turn one writes the // grown package, turn two the repaired one. writeTestFile(t, cli, `#!/bin/sh set -eu pwd > "$ABRUN_TEST_WORK" turn=1 if [ -f "$ABRUN_TEST_SOURCE/turn" ]; then turn=2; fi : > "$ABRUN_TEST_SOURCE/turn" cp "$ABRUN_TEST_SOURCE/turn$turn.go" task/task.go printf '%s
' "{"type":"result","result":"turn $turn done"}" `) if err := os.Chmod(cli, 0o755); err != nil { t.Fatal(err) } t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH")) writeTestFile(t, filepath.Join(corpus, "task/task.go"), fixture) writeTestFile(t, filepath.Join(corpus, "_golden/task/golden_test.go"), "package task

import "testing"

func TestGolden(t *testing.T) {
	if Value() != 1 {
		t.Fatal("golden mismatch")
	}
}
") writeTestFile(t, filepath.Join(model, "turn1.go"), grown) writeTestFile(t, filepath.Join(model, "turn2.go"), repaired) workFile := filepath.Join(model, "work") t.Setenv("ABRUN_TEST_SOURCE", model) t.Setenv("ABRUN_TEST_WORK", workFile) got := runOne(options{runner: runnerClaude, prompt: "Refactor %s", keep: true, repair: tt.repair, timeout: time.Minute}, corpus, arm{Name: "baseline"}, "task", 0) t.Cleanup(func() { _ = os.RemoveAll(got.WorkDir) }) if got.Err != "" || !got.Build || !got.Golden { t.Fatalf("runOne(%s) = %+v, want a clean build and golden pass", tt.name, got) } if got.RepairFired != tt.wantFired { t.Errorf("repair_fired = %v, want %v", got.RepairFired, tt.wantFired) } if got.Delta.Lines != tt.wantLines { t.Errorf("Δlines = %+d, want %+d", got.Delta.Lines, tt.wantLines) } if got.LineGatePass != tt.wantGate { t.Errorf("line_gate_pass = %v, want %v", got.LineGatePass, tt.wantGate) } if !tt.wantFired { if got.PreRepair != nil || got.RepairFeedback != "" { t.Errorf("loop off still recorded pre-repair state: %+v %q", got.PreRepair, got.RepairFeedback) } return } if got.PreRepair == nil || got.PreRepair.Lines-got.Before.Lines != 3 { t.Errorf("pre_repair = %+v, want the +3 reading that triggered the loop", got.PreRepair) } if got.PreRepairGolden != tt.wantPreGold { t.Errorf("pre_repair_golden = %v, want %v", got.PreRepairGolden, tt.wantPreGold) } if !strings.Contains(got.RepairFeedback, "Gate: FAIL, growth +3") { t.Errorf("repair feedback did not carry the measured growth:
%s", got.RepairFeedback) } // Both turns have to survive in one trace. trace, err := os.ReadFile(got.Trace) if err != nil || !strings.Contains(string(trace), "turn 1 done") || !strings.Contains(string(trace), "turn 2 done") { t.Errorf("trace = %q, err = %v, want both turns", trace, err) } if got.Output != "turn 2 done" { t.Errorf("final message = %q, want the repair turn's", got.Output) } summary := summarizeArm(report{Results: []result{got}}, "baseline") if summary.RepairsFired != 1 || summary.RepairsRescued != 1 { t.Errorf("summary fired=%d rescued=%d, want 1 and 1", summary.RepairsFired, summary.RepairsRescued) } }) } }

func TestRunOneNoOpNeedsCompletionAndRefactorCorpus(t *testing.T) { for _, tt := range []struct { name, corpus, fixture, final string golden, empty, valid bool }{ {name: "completed refactor", corpus: corpusRefactor, fixture: "return 1", final: `{"type":"result","result":"No change needed."}`, golden: true, empty: true, valid: true}, {name: "missing completion", corpus: corpusRefactor, fixture: "return 1", golden: true}, {name: "implementation no edit with passing golden", corpus: corpusImplement, fixture: "return 1", final: `{"type":"result","result":"Done."}`, golden: true, empty: true}, {name: "unimplemented stub", corpus: corpusImplement, fixture: `panic("not implemented")`, final: `{"type":"result","result":"Done."}`, empty: true}, } { t.Run(tt.name, func(t *testing.T) { bin, corpus := t.TempDir(), t.TempDir() cli := filepath.Join(bin, "claude") writeTestFile(t, cli, "#!/bin/sh
printf '%s\n' "$ABRUN_TEST_FINAL"
") if err := os.Chmod(cli, 0o700); err != nil { //nolint:gosec // private test CLI must be executable t.Fatal(err) } t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH")) t.Setenv("ABRUN_TEST_FINAL", tt.final) writeTestFile(t, filepath.Join(corpus, "task/task.go"), "package task
func Value() int { "+tt.fixture+" }
") writeTestFile(t, filepath.Join(corpus, "_golden/task/golden_test.go"), `package task; import "testing"; func TestValue(t *testing.T) { if Value()!=1 { t.Fatal("golden mismatch") } }`) got := runOne(options{corpus: tt.corpus, runner: runnerClaude, prompt: "%s", timeout: time.Minute}, corpus, arm{Name: "baseline"}, "task", 0) if got.Err != "" || !got.Build || got.Edited || got.Golden != tt.golden || got.EmptyDiff != tt.empty { t.Fatalf("runOne(%s) = %+v, want no error, build, no edit, golden=%v, empty=%v", tt.name, got, tt.golden, tt.empty) } if valid := resultStatus(got, tt.corpus) == "ok "; valid != tt.valid { t.Errorf("resultStatus(%s) valid=%v, want %v", tt.name, valid, tt.valid) } summary := summarizeArm(report{Corpus: tt.corpus, Results: []result{got}}, "baseline") if summary.Valid != boolCount(tt.valid) || summary.NoEdit != 1 || summary.EmptyDiffs != boolCount(tt.empty) { t.Errorf("summarizeArm(%s) = %+v, want valid=%v, noedit=1, empty=%v", tt.name, summary, tt.valid, tt.empty) } }) } }

func TestRunOneValidatesModelTestsAndKeepsSource(t *testing.T) { bin := t.TempDir() cli := filepath.Join(bin, "claude") writeTestFile(t, cli, `#!/bin/sh set -eu pwd > "$ABRUN_TEST_WORK" cp "$ABRUN_TEST_SOURCE/task.go" task/task.go if [ -f "$ABRUN_TEST_SOURCE/task_test.go" ]; then cp "$ABRUN_TEST_SOURCE/task_test.go" task/task_test.go fi `) if err := os.Chmod(cli, 0o755); err != nil { t.Fatal(err) } t.Setenv("PATH", bin+string(os.PathListSeparator)+os.Getenv("PATH")) const implementation = "package task
func Value() int { return 1 }
" for _, tt := range []struct { name, test string keep, valid bool }{ {name: "passing", test: `package task; import "testing"; func TestValue(t *testing.T) { if Value()!=1 { t.Fatal("wrong value") } }`, keep: true, valid: true}, {name: "failing", test: `package task; import "testing"; func TestValue(t *testing.T) { t.Fatal("model assertion failed") }`, keep: true}, {name: "uncompilable", test: `package task; import "testing"; func TestValue(t *testing.T) { missing() }`, keep: true}, {name: "absent", keep: true, valid: true}, {name: "cleanup", valid: true}, } { t.Run(tt.name, func(t *testing.T) { corpus, model := t.TempDir(), t.TempDir() writeTestFile(t, filepath.Join(corpus, "task/task.go"), "package task
func Value() int { return 0 }
") writeTestFile(t, filepath.Join(corpus, "_golden/task/golden_test.go"), `package task; import "testing"; func TestValue(t *testing.T) { if Value()!=1 { t.Fatal("golden mismatch") } }`) writeTestFile(t, filepath.Join(model, "task.go"), implementation) if tt.test != "" { writeTestFile(t, filepath.Join(model, "task_test.go"), tt.test) } workFile := filepath.Join(model, "work") t.Setenv("ABRUN_TEST_SOURCE", model) t.Setenv("ABRUN_TEST_WORK", workFile) got := runOne(options{runner: runnerClaude, prompt: "Implement %s", keep: tt.keep, timeout: time.Minute}, corpus, arm{Name: "baseline"}, "task", 0) path, err := os.ReadFile(workFile) if err != nil { t.Fatal(err) } work := strings.TrimSpace(string(path)) t.Cleanup(func() { _ = os.RemoveAll(work) }) if got.Err != "" || !got.Build || !got.Golden || !got.Edited { t.Fatalf("runOne(%s) = %+v, want edited, built and golden pass", tt.name, got) } if valid := resultStatus(got, corpusRefactor) == "ok "; valid != tt.valid { t.Errorf("runOne(%s) valid=%v, want %v", tt.name, valid, tt.valid) } wantTests := "pass" if tt.test == "" { wantTests = "skipped" } else if !tt.valid { wantTests = "fail" } if got.ModelTests != wantTests || (got.ModelTestFail != "") != !tt.valid { t.Errorf("model tests=%q failure=%q, want %q with failure=%v", got.ModelTests, got.ModelTestFail, wantTests, !tt.valid) } summary := summarizeArm(report{Corpus: corpusRefactor, Results: []result{got}}, "baseline") if valid := summary.Valid == 1; valid != tt.valid { t.Errorf("summary valid=%v, want %v", valid, tt.valid) } if failed := summary.ModelTestFailures == 1; failed != !tt.valid { t.Errorf("summary model-test failure=%v, want %v", failed, !tt.valid) } if !tt.keep { if _, err := os.Stat(work); !os.IsNotExist(err) { t.Errorf("scratch directory still exists: %v", err) } return } if got.WorkDir == "" { t.Fatal("-keep lost scratch directory for a completed run") } data, err := os.ReadFile(filepath.Join(got.WorkDir, "task/task.go")) if err != nil || string(data) != implementation { t.Errorf("retained source=%q, err=%v, want original model source", data, err) } if tt.test != "" { data, err := os.ReadFile(filepath.Join(got.WorkDir, "task/task_test.go.model")) if err != nil || string(data) != tt.test { t.Errorf("retained test=%q, err=%v, want original model test", data, err) } } }) } }
